public interface OrderPort { Receipt place(Order order) throws OrderRejected; }

final class LegacyOrderAdapter implements OrderPort {   // only class importing acme.legacy
    private final LegacyClient client;
    public Receipt place(Order order) {
        try {
            var dto = LegacyOrderMapper.INSTANCE.toDto(order);
            return Receipt.from(client.submit(dto));     // local type out
        } catch (LegacyRemoteException e) {
            throw new OrderRejected(e.getMessage(), e);  // error vocabulary translated
        }
    }
}
